// Convenience: every subject that currently has a hardwired preset.
// Preset sequences that span several grades prefix each topic with its grade
// ("Grade 2 · ...", "Graad 2 · ...", "Kereite ya 2 · ..."). A class only teaches
// its own grade, so the sequence is narrowed before it is copied onto a class.
const GRADE_PREFIX = /^(?:Grade|Graad|Kereite ya|IBanga)\s+(R|\d+)\s+·/;

// The curriculum a class should be created with: the departmental ATP sequence
// and source name where the subject has been re-directed for the year, and the
// CAPS-derived preset sequence otherwise. Single decision point for every class
// creation path (teacher, parent, tutor) so they cannot drift apart.
export async function curriculumForClass(
  preset: PresetEntry,
  grade: number,
): Promise<{ sequence: string[]; sourceName: string; source: "atp" | "caps" }> {
  const atp = await atpSequenceForClass(preset.subject, grade);
  if (atp) return { sequence: atp.sequence, sourceName: atp.sourceName, source: "atp" };
  return {
    sequence: presetSequenceForGrade(preset, grade),
    sourceName: preset.sourceName,
    source: "caps",
  };
}

export function presetSequenceForGrade(preset: PresetEntry, grade: number): string[] {
  if (preset.gradeMin === preset.gradeMax) return preset.sequence;
  const token = grade === GRADE_R ? "R" : String(grade);
  const scoped = preset.sequence.filter((topic) => GRADE_PREFIX.exec(topic)?.[1] === token);
  // A multi-grade sequence without any grade prefixes (e.g. a document that has
  // not yet been split per grade) is used whole as a fallback.
  return scoped.length ? scoped : preset.sequence;
}

export function presetSubjects() {
  return Array.from(new Set(PRESET_CURRICULA.map((entry) => entry.subject)));
}

// Longest hardwired subject label. Route schemas validate the subject a client
// posts, and the dropdowns are fed straight from this catalog, so the limit has
// to be derived from the catalog itself — a fixed cap silently rejects valid
// preset subjects once a longer label (e.g. an African-language FAL title) is
// added.
export const PRESET_SUBJECT_MAX_LENGTH = PRESET_CURRICULA.reduce(
  (longest, entry) => Math.max(longest, entry.subject.length),
  0,
);

// Subjects a given grade may open a class for; a subject can appear in several
// phases (e.g. Mathematics in the Foundation and Intermediate Phase).
export function presetSubjectsForGrade(grade: number) {
  return PRESET_CURRICULA.filter((entry) => grade >= entry.gradeMin && grade <= entry.gradeMax).map((entry) => entry.subject);
}

export function presetForSubject(subject: string, grade: number): PresetEntry | null {
  return PRESET_CURRICULA.find((entry) => entry.subject === subject && grade >= entry.gradeMin && grade <= entry.gradeMax) ?? null;
}

// Upserts the registry into the catalog table (idempotent — used by the
// schema bootstrap and useful when the registry gains entries).
export async function syncPresetCurricula() {
  for (const entry of PRESET_CURRICULA) {
    await db
      .insert(presetCurriculaTable)
      .values({
        phase: entry.phase,
        subject: entry.subject,
        gradeMin: entry.gradeMin,
        gradeMax: entry.gradeMax,
        sourceName: entry.sourceName,
        sequence: entry.sequence,
        assessmentGuide: entry.assessmentGuide || null,
      })
      .onConflictDoUpdate({
        target: [presetCurriculaTable.phase, presetCurriculaTable.subject, presetCurriculaTable.gradeMin, presetCurriculaTable.gradeMax],
        set: {
          sequence: entry.sequence,
          sourceName: entry.sourceName,
          // Only overwrite the guide from the registry when a non-empty one is
          // hardwired; uploaded guides (until a set endpoint ships) are kept.
          ...(entry.assessmentGuide ? { assessmentGuide: entry.assessmentGuide } : {}),
        },
      });
  }
}

// Gate: a class can only be created against a preset subject at a covered
// grade. Returns the preset on success, or null when the subject is locked.
export async function resolvePresetForClass(subject: string, grade: number) {
  const preset = presetForSubject(subject, grade);
  if (!preset) return null;
  const [row] = await db
    .select()
    .from(presetCurriculaTable)
    .where(
      and(
        eq(presetCurriculaTable.subject, preset.subject),
        eq(presetCurriculaTable.gradeMin, preset.gradeMin),
        eq(presetCurriculaTable.gradeMax, preset.gradeMax),
      ),
    )
    .limit(1);
  return { preset, row: row ?? null };
}

export async function listPresetCurricula() {
  const rows = await db
    .select()
    .from(presetCurriculaTable)
    .orderBy(sql`${presetCurriculaTable.gradeMin}, ${presetCurriculaTable.subject}`);
  return rows.map((row) => ({
    id: row.id,
    phase: row.phase,
    subject: row.subject,
    gradeMin: row.gradeMin,
    gradeMax: row.gradeMax,
    sourceName: row.sourceName,
    sequence: row.sequence,
    hasAssessmentGuide: Boolean(row.assessmentGuide),
  }));
}

// One-off (idempotent) migration for the curriculum lock: any class whose
// curriculum was uploaded by a teacher, parent or tutor is reset to the preset
// curriculum for its subject and grade. The uploaded text and the sequence it
// produced are preserved in curriculum_archive — nothing is deleted.
export async function lockClassesToPresetCurricula() {
  const rows = await db.select().from(classesTable);
  let migrated = 0;
  for (const row of rows) {
    const subject = row.presetSubject || row.subject;
    const preset = presetForSubject(subject, row.grade);
    if (!preset) continue;
    const uploaded = Boolean(row.curriculumText && !/^Preset curriculum:/i.test(row.curriculumText));
    const capsSequence = presetSequenceForGrade(preset, row.grade);
    // Where the department has re-directed this subject for the year, the ATP is
    // the authority and its sequence replaces the CAPS-derived one. Retained
    // subjects are untouched, so the great majority of classes keep their plan.
    const atp = await atpSequenceForClass(preset.subject, row.grade);
    const presetSequence = atp ? atp.sequence : capsSequence;
    // A class already marked as locked is left completely alone, even if the
    // preset itself has since changed. Comparing the stored sequence against the
    // current preset instead would re-run the lock every time a preset gains a
    // topic, and the re-run used to rewind currentTopicIndex to 0 — silently
    // sending a class that is half-way through the year back to its first topic.
    const alreadyLocked = Boolean(row.curriculumLockedAt);
    if (alreadyLocked) continue;
    await db
      .update(classesTable)
      .set({
        presetSubject: preset.subject,
        lessonSequence: presetSequence,
        // Only a genuinely owner-uploaded curriculum resets pacing. A class that
        // was already following a preset keeps its position, clamped to the new
        // sequence length in case the sequence shrank.
        currentTopicIndex: uploaded
          ? 0
          : Math.max(0, Math.min(row.currentTopicIndex, presetSequence.length - 1)),
        curriculumText: `Preset curriculum: ${atp ? atp.sourceName : preset.sourceName}`,
        curriculumFileName: atp ? atp.sourceName : preset.sourceName,
        curriculumLockedAt: new Date(),
        ...(uploaded && row.curriculumArchive === null
          ? {
              curriculumArchive: JSON.stringify({
                archivedAt: new Date().toISOString(),
                fileName: row.curriculumFileName,
                text: row.curriculumText,
                lessonSequence: row.lessonSequence,
              }),
            }
          : {}),
      })
      .where(eq(classesTable.id, row.id));
    migrated += 1;
  }
  return migrated;
}

// Resolves the per-module assessment guideline for a class's preset subject,
// when one has been supplied (e.g. a Stadio module guideline). Shared by the
// learner submission path and the background marking retry.
export async function assessmentGuideForClass(
  classRow: Pick<typeof classesTable.$inferSelect, "presetSubject" | "grade"> | null,
): Promise<string | undefined> {
  if (!classRow?.presetSubject) return undefined;
  const [row] = await db
    .select({ assessmentGuide: presetCurriculaTable.assessmentGuide })
    .from(presetCurriculaTable)
    .where(
      and(
        eq(presetCurriculaTable.subject, classRow.presetSubject),
        lte(presetCurriculaTable.gradeMin, classRow.grade),
        gte(presetCurriculaTable.gradeMax, classRow.grade),
      ),
    )
    .limit(1);
  return row?.assessmentGuide?.trim() || undefined;
}
